export class StatisticsManager{constructor(){this.correctKeystrokes=0,this.incorrectKeystrokes=0,this.wordsTyped=0,this.enemiesDefeated=0,this.bossesDefeated=0,this.playtimeSeconds=0}recordKeystroke(e){e?this.correctKeystrokes++:this.incorrectKeystrokes++}recordWordTyped(){this.wordsTyped++}recordEnemyDefeated(e=!1){this.enemiesDefeated++,e&&this.bossesDefeated++}addPlaytime(e){this.playtimeSeconds+=e}getStatsData(){const e=this.correctKeystrokes+this.incorrectKeystrokes,s=e>0?this.correctKeystrokes/e*100:0,t=this.playtimeSeconds/60;return{wpm:t>0?Math.round(this.correctKeystrokes/5/t):0,accuracy:parseFloat(s.toFixed(2)),wordsTyped:this.wordsTyped,enemiesDefeated:this.enemiesDefeated,bossesDefeated:this.bossesDefeated,playtimeSeconds:Math.floor(this.playtimeSeconds)}}}